window.kbPageData["views/practice/s-171ebed39b4fe1cf"] = {"key":"practice/s-171ebed39b4fe1cf","state":{"route":"practice/s-171ebed39b4fe1cf"},"tree":"<a data-toc-link href=\"#skills/shenlun\">申论技能首页</a><details data-branch=\"module-归纳概括\"><summary>归纳概括</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c898afc5816920c2\">概括作用与成效</a><a data-toc-link href=\"#practice/s-0b47c7faa1dcfbc7\">提炼做法与经验</a><a data-toc-link href=\"#practice/s-75a1eb1e46268fd8\">归类概括材料中的问题</a><a data-toc-link href=\"#practice/s-4863baf2b4febcf4\">配对概括做法与成效</a><a data-toc-link href=\"#practice/s-c94c813ed743298a\">从材料提取概念特征</a><a data-toc-link href=\"#practice/s-4da331cba0998f2b\">分条梳理不同立场与分歧</a></div></details><details data-branch=\"module-综合分析\"><summary>综合分析</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-43e39afd29a17e74\">解释含义与作用</a><a data-toc-link href=\"#practice/s-599008555ed60dda\">分析现象形成的原因</a><a data-toc-link href=\"#practice/s-93367fee5c934df6\">从案例推导改进建议</a></div></details><details data-branch=\"module-提出对策\"><summary>提出对策</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c6bd983baf5dd3ae\">根据问题成因逐项提出措施</a><a data-toc-link href=\"#practice/s-ecba3f8c2c1d3b9b\">将外地经验转化为本地措施</a><a data-toc-link href=\"#practice/s-9b570af6b9f113ee\">按治理环节组织对策</a><a data-toc-link href=\"#practice/s-91888cb77ec12615\">从材料反馈中提炼改进建议</a></div></details><details data-branch=\"module-应用文写作\" open><summary>应用文写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-171ebed39b4fe1cf\" aria-current=\"page\">汇报与交流发言</a><a data-toc-link href=\"#practice/s-b92b682e65d12042\">面向公众动员参与</a><a data-toc-link href=\"#practice/s-cabc6af5d656b214\">宣传介绍与活动报道</a><a data-toc-link href=\"#practice/s-5cd530a611f08110\">编写案例摘要</a><a data-toc-link href=\"#practice/s-9f175b7eb1a79028\">陈述事由与请求</a><a data-toc-link href=\"#practice/s-38dece0b54a49be3\">拟定工作事项与措施</a><a data-toc-link href=\"#practice/s-c8dfde3ede3eadab\">撰写案例短评或点评</a></div></details><details data-branch=\"module-文章写作\"><summary>文章写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-b8139af04b609dce\">展开分论点的论证</a><a data-toc-link href=\"#practice/s-4fdadcb77809c673\">围绕中心论点组织分论点</a><a data-toc-link href=\"#practice/s-ab43045e4cab9ffe\">从材料立意并确立中心论点</a></div></details>","packs":{"国考 2023 副省级 申论#3":"6cc382234f52e794814c525f","国考 2024 副省级 申论#4":"6cc382234f52e794814c525f","国考 2024 行政执法 申论#3":"6cc382234f52e794814c525f","国考 2025 行政执法 申论#4":"b9eead520446619ae2f0a4ff","江苏 2024 C类 申论#4":"b9eead520446619ae2f0a4ff"},"questions":{"国考 2023 副省级 申论#3":{"paper":"国考 2023 副省级 申论","n":3,"mod":"申论","src":["1b62f4f7aa551cdd783e.pdf",4],"asrc":["269b01c80926c8585ace.pdf",2]},"国考 2024 副省级 申论#4":{"paper":"国考 2024 副省级 申论","n":4,"mod":"申论","src":["22a70a7d604f43d79958.pdf",4],"asrc":["e63c52d7634f0ab7a98f.pdf",3]},"国考 2024 行政执法 申论#3":{"paper":"国考 2024 行政执法 申论","n":3,"mod":"申论","src":["b9a9a500aad1608fddd0.pdf",4],"asrc":["b899d5c3aecda01e69ec.pdf",2]},"国考 2025 行政执法 申论#4":{"paper":"国考 2025 行政执法 申论","n":4,"mod":"申论","src":["dbb2469ea58338709f40.pdf",4],"asrc":["d1fc3fe21ef6ae3b1ae6.pdf",3]},"江苏 2024 C类 申论#4":{"paper":"江苏 2024 C类 申论","n":4,"mod":"申论","src":["a7cfdee83e6ff0de5e71.pdf",3],"asrc":["525cbf0b49bf46168baf.pdf",2]}},"first":{"qs":{"国考 2023 副省级 申论#3":{"paper":"国考 2023 副省级 申论","n":3,"mod":"申论","src":["1b62f4f7aa551cdd783e.pdf",4],"asrc":["269b01c80926c8585ace.pdf",2],"m":["e98d4ffa1f6cfa25"],"task":"以J市文史学家叶教授的身份，依据材料3起草一份不超过400字的建议，说明凤凰河流域文化建设的意义、现存问题和可行措施。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据是材料中的流域治理案例和文化建设条件，所述协调小组成立及全线通水分别发生于2018年和2021年，均在指定窗口之前。"},"links":[{"id":"k-713e68763e49192b","label":"流域生态复苏与流域文化传承相互促进","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"动的河能激活文化之河，文化之河也能反哺流动的河","why":"材料用双向促进关系说明加强凤凰河流域文化建设的意义。","origin":"逐题标记"},{"id":"k-c7fdb9fb3d9a8a38","label":"跨行政区流域文化遗产保护需要统一规划和跨部门协同","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"无法统筹流域内相关部门形成保护合力","why":"文化遗产跨省市分布、保护开发状况各异，需要在全流域建立协调机制并制定系统性保护传承规划。","origin":"逐题标记"},{"id":"k-6c17be7420f2871c","label":"流域文化核心内容的提炼以全流域调查研究为基础","catalog_id":null,"type":"方法与技能","role":"直接考查","field":"answer","quote":"整体推进调查研究，提炼文化核心内容","why":"针对文化内涵认识分散和既有调查难以整体推进的问题，参考答案把统筹调查与提炼核心内容对应起来。","origin":"逐题标记"},{"id":"k-5f0693bbb316def1","label":"生态修复为生态旅游与文化旅游融合提供条件","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"就可以推动生态旅游和文化旅游融合发展","why":"自然风光和生态环境的恢复能为沿岸文化资源的旅游利用提供条件。","origin":"逐题标记"},{"id":"k-77b440d77f8e1fc4","label":"文化资源活化利用需要融入群众生活","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"文化的生命在于‘用’，在于融入群众生活。","why":"材料以文化景观和数字沉浸式体验说明如何让群众接触并使用流域文化资源。","origin":"逐题标记"},{"id":"s-171ebed39b4fe1cf","label":"按意义、问题和对策归纳材料并组织正文","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"意义全面，问题精准，措施可行","why":"需要从材料提取建设价值和现实短板，并组织能够回应这些短板的措施。","origin":"逐题标记"},{"id":"s-ecba3f8c2c1d3b9b","label":"从同类治理案例迁移可行措施","catalog_id":null,"type":null,"role":"解题依据","field":"M1","quote":"凤凰河生态治理的模式给了叶教授新的启发","why":"需要将生态治理中的全流域协调和专业规划转化为文化遗产保护传承措施。","origin":"逐题标记"}],"stem":"假如你是J市文史学家叶教授，请根据“给定资料3”，起草一份《关于加强凤凰河流域文化建设的建议》。（20\n分）\n要求：\n（1）意义全面，问题精准，措施可行；\n（2）层次分明，逻辑清晰，表述准确；\n（3）不超过400字。","options":[],"answer":"","analysis":"关于加强凤凰河流域文化建设的建议\n尊敬的领导：\n  凤凰河流域文化建设意义重大，能传承保护文化遗产，还能反哺生态环境，带动沿岸经济文化发展。但目前存\n在缺乏统一的文化核心内容，地域间、部门间未形成合力，未融入群众生活等问题。基于此，我提出以下建议：\n  一、全流域“一盘棋”。牵头成立文化工作领导小组，成员涵盖沿线城市主要领导，制定系统性保护传承战略规\n划；统筹流域内相关部门，形成保护合力；整体推进调查研究，提炼文化核心内容。二、活化利用文化资源。充分\n利用沿河文化资源，加速恢复风光和生态，文化旅游、生态旅游同步、融合发展；创新发展，修建现代文化景观，\n汇聚人气，开发APP，利用数字技术，实现沉浸式体验。\n  以上建议，供领导参考。\n                                                 建议人：叶某某\n                                               XXXX年XX月XX日\n  参考答案说明：（1）格式方面，本参考答案写到了“标题”“称谓”“正文”“落款”四个部分。（2）正文部分，一方面\n从内容上来看，围绕“凤凰河流域文化建设”这一主题，本参考答案的开头先写到了“凤凰河流域文化建设的意义、问\n题”；主体部分从“全流域‘一盘棋’”“活化利用文化资源”两个方面给出了具体建议；结尾部分添加了结束语。另一方\n面，形式上，本参考答案做到了分段、分条撰写，整体上条理较为清晰。","figs":[],"state":"已标记","notes":[],"domains":["文化","公共管理","生态环境"],"nature":"综合题","current":false},"国考 2024 副省级 申论#4":{"paper":"国考 2024 副省级 申论","n":4,"mod":"申论","src":["22a70a7d604f43d79958.pdf",4],"asrc":["e63c52d7634f0ab7a98f.pdf",3],"m":["6644520b217e1626"],"task":"以督导调研组成员身份，依据材料4草拟一份不超过500字的汇报正文，概括C市高标准农田建设成效和存在的问题，并逐项提出改进建议。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答所需的地方调研情况、项目要求和整改依据均由材料给出，题目未要求识别窗口内发生的特定事件或政策部署。"},"links":[{"id":"k-3e95b77eeabd0099","label":"高标准农田建设","catalog_id":"18b15dd81bc52dab","type":"原理与机制","role":"直接考查","field":"M1","quote":"巩固和提高粮食生产能力、保障国家粮食安全的关键举措","why":"材料明确了高标准农田建设的目标，汇报需结合灌溉条件和亩均效益的改善说明建设成效。","origin":"逐题标记"},{"id":"k-7abd42f3d3e3ebc0","label":"农田连片整合促进土地流转与规模经营","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"统一整合分散土地，进行土地流转，推动规模化种植","why":"材料以长平县为例，说明整合分散地块后可通过土地流转促进规模经营，并增加农户租金和务工收入。","origin":"逐题标记"},{"id":"k-be0407994ebcc946","label":"农田基础设施改善为因地制宜发展特色农业创造条件","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"M1","quote":"各乡因地制宜推进产业结构调整","why":"材料以稻油、稻鱼等特色产业的发展说明基础设施改善后如何优化产业结构、提高农业综合效益。","origin":"逐题标记"},{"id":"k-e6fbd439ca279965","label":"高标准农田原则上全部用于粮食生产","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"M1","quote":"高标准农田原则上全部用于\n粮食生产","why":"粮食生产用途要求为判断现有果园划入规划地块时的图实不符问题提供依据。","origin":"逐题标记"},{"id":"k-fbe56f334fecd67b","label":"高标准农田建设项目须按批复设计实施和验收，变更须事先获批","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"审核验收工作需严格执行批复的初步设计，未经批复同意的调整不予通过。","why":"项目应先报批再调整，验收应核对批复设计及获批变更，据此判断仅核对完成数量的做法存在问题。","origin":"逐题标记"},{"id":"k-abf275cf7d287f0a","label":"高标准农田田间道的连接对象与通行用途","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"M1","quote":"田间道是指连接田块与村庄、田块之间","why":"田间道用于农田耕作及农用物资、农产品运输，连接田块的要求是判断福树村所修道路是否合规的依据。","origin":"逐题标记"},{"id":"k-1d9d287163ec3883","label":"C市改造后高标准农田须由施工单位统一增施有机肥","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"M1","quote":"有机肥应通过施工单位统一实施入田，严禁“以发代施”","why":"C市的施肥要求用于判断按人口分发有机肥的做法，并明确整改应落实到统一施肥入田。","origin":"逐题标记"},{"id":"s-171ebed39b4fe1cf","label":"从调研材料中归纳建设成效与实施问题","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"从成果、问题、建议三个方面展开","why":"将不同地区的走访事例提炼为可并列呈现的成效和问题要点，为汇报正文组织材料。","origin":"逐题标记","originalId":"s-4c269be6e630b720"},{"id":"s-c6bd983baf5dd3ae","label":"按问题成因和管理要求逐项拟定整改措施","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"问题与建议一一对应。","why":"根据每项问题的成因或违反的要求，确定相应的整改环节和做法。","origin":"逐题标记","originalId":"s-87f603578bf566aa"}],"stem":"“给定材料4”反映了C市高标准农田建设过程中的一些情况，调研结束后，督导调研组拟向局领导汇报调研情况，\n并提出改进建议。假如你是调研组成员，请草拟汇报的主要内容。（20分）\n要求：\n（1）紧扣材料，内容全面；\n（2）简明扼要，条理清晰；\n（3）不超过500字。","options":[],"answer":"","analysis":"一、成果：1.农田得以改良。修复重建水利和农田配套设施，将旱田改造成水浇田，让种田更轻松，土地产值和\n亩均效益提升，农户种粮积极性提高。2.收入得以提升。统一整合分散土地，进行土地流转，推动规模化种植，提升\n土地租金收入，还通过务工增加工资收入。3.产业结构得以优化。农田基础设施条件显著改善，特色优势产业稳步发\n展，农业综合效益明显提升。\n  二、问题：1.实际和规划不符。上级政府不了解基层情况，直接划分区域、分派任务。2.审核验收不严格。随意\n调整和变更地块，仅要求完成数与规划数一致。3.配套设施不合规。占用高标准农田建设资金，修建非“田间道”。4.\n田间管理不到位。有机肥“以发代施”，导致村民挪用专用有机肥。\n  三、建议：1.确保规划符合实际。做规划前深入开展调研，形成意见后由基层确认，确保符合基层情况。2.严格\n把关审核验收。审核验收工作需严格执行批复的初步设计，未经批复同意的调整不予通过。3.严肃落实设施建设。严\n格审核配套设施规划图，做到专款专用，确保道路等设施建设合乎规定。4.切实加强田间管理。有机肥严格通过施工\n单位统一实施入田，杜绝将肥料发放给农户的现象。\n  参考答案说明：（1）“草拟汇报”提示本题为公文题，但题干要求写“主要内容”，所以不必考虑格式，只写正文的\n主体部分即可。（2）本参考答案宏观上从成果、问题、建议三个方面展开。其中，成果围绕“农田得以改良”“收入得\n以提升”“产业结构得以优化”三个方面进行了分条撰写；问题围绕“实际和规划不符”“审核验收不严格”“配套设施不合\n规”“田间管理不到位”四个方面进行了分条撰写；建议围绕“确保规划符合实际”“严格把关审核验收”“严肃落实设施建\n设”“切实加强田间管理”四个方面进行了分条撰写。问题与建议一一对应。各条要点之间在内容上相互并列，没有交\n叉。","figs":[],"state":"已标记","notes":[],"domains":["公共管理","经济"],"nature":"综合题","current":false},"国考 2024 行政执法 申论#3":{"paper":"国考 2024 行政执法 申论","n":3,"mod":"申论","src":["b9a9a500aad1608fddd0.pdf",4],"asrc":["b899d5c3aecda01e69ec.pdf",2],"m":["79740cef9272f9f5"],"task":"以有关部门工作人员的身份，根据材料3的座谈发言，在400字以内撰写一份涵盖非遗法实施成效、不足和改进建议的情况报告。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据是材料所载实施情况与座谈意见，座谈时间和窗口内具体政策部署均无需另行判定。"},"links":[{"id":"k-617bc5b51533628c","label":"非遗法实施增强企业信心并明确保护传承传播方向","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"给企业发展注入新动力，坚定产业发展战略信心。","why":"参考答案将产业信心和企业业务方向列为实施成效。","origin":"逐题标记"},{"id":"k-663932a5e61c3ed9","label":"非遗法实施促进公众认识民间文化价值","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"让人们逐步认识民间文化的价值。","why":"公众对民间文化价值的认识是报告需概括的实施成效。","origin":"逐题标记"},{"id":"k-ccaa22104463ae9e","label":"非遗法实施带动政府支持非遗传承并需加强资金与场地保障","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"在资金、场地上进一步提供保障","why":"传承人的工作室和扶持资金体现已有支持，其发言也提出加强资源保障的建议。","origin":"逐题标记"},{"id":"k-b7e2ea515f503791","label":"非物质文化遗产的法定内涵与认定边界","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"M1","quote":"各族人民世代相传并视为其文化遗产组成部分","why":"世代相传是识别地方将新创内容误认作非遗的依据，法定范围还包括相关实物和场所。","origin":"逐题标记"},{"id":"k-e6158c82c8dad87b","label":"非遗保护人才队伍与专业化、信息化要求的差距","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"非遗保护专业化、信息化要求高，现有人才队伍不适应。","why":"保护工作的能力要求与人才队伍现状之间的差距是实施不足之一。","origin":"逐题标记"},{"id":"k-46193cdb17edb9e5","label":"非遗传承中的知识产权认定需区分共同遗产与具有个性的再创作","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"关于非遗传承的知识产权认定仍然比较复杂","why":"参考答案将权利认定困难列为不足，律师以共同遗产和体现创作者个性的再创作说明认定中的区别。","origin":"逐题标记"},{"id":"k-c2744839d74471e4","label":"地方非遗法落实不足表现为保护传承义务缺位和过度开发","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"M1","quote":"有的不履行非遗保护、传承义务，有的以活化名义进行过度开发。","why":"两种表现具体说明参考答案所概括的部分地方落实不到位。","origin":"逐题标记"},{"id":"k-7aba68b5e065012d","label":"非遗原真性保护兼顾项目结构与生存环境","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"保留非遗完整结构与秩序，重视非遗生存环境的整体性保护，确保原真性。","why":"改进建议要求同时维护非遗自身的完整结构和支撑其存续的空间、组织等条件。","origin":"逐题标记"},{"id":"k-8b0c3c8f8ca79697","label":"代表性传承人的带徒授艺考核","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"对传承人进行严格考核，保证带徒授艺规范有序。","why":"参考答案将严格考核作为规范带徒授艺、落实后继人才培养责任的改进措施。","origin":"逐题标记"},{"id":"k-386ce3913640401f","label":"非遗活化以深入了解项目和遵循文化演化规律为前提","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"在对非遗本身进行细致深入了解之后","why":"参考答案将深入了解项目和遵循文化演化规律作为选择保护、传承与活化方式的条件。","origin":"逐题标记"},{"id":"s-171ebed39b4fe1cf","label":"按成效、不足和改进建议归并多方座谈发言","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"围绕非遗法实施的成效、不足\n和改进建议，写一份情况报告。","why":"需从不同参会者的发言中提炼要点、合并相近信息，并按报告的三个方面组织内容。","origin":"逐题标记","originalId":"s-fe06a640da7420e9"}],"stem":"如果你是“给定材料3”中有关部门的工作人员，请根据座谈会参会人员的发言内容，围绕非遗法实施的成效、不足\n和改进建议，写一份情况报告。（20分）\n要求：\n（1）紧扣材料，内容全面；\n（2）要点突出，条理清晰，语言准确；\n（3）不超过400字。","options":[],"answer":"","analysis":"关于非遗法实施情况座谈会的情况报告\n  非遗法已颁布12年，其实施情况，座谈会讨论如下：\n  一、成效：1.给企业发展注入新动力，坚定产业发展战略信心。2.为从事非遗保护、传承和传播的企业指明方\n向。3.为非遗保护传承争取到各级政府资源支持。4.让人们逐步认识民间文化的价值。\n  二、不足：1.非遗保护专业化、信息化要求高，现有人才队伍不适应。2.地方混淆非遗概念，将现代的、改编的\n甚至糟粕的内容当遗产。3.非遗传承的知识产权认定仍较复杂。4.部分地方对非遗法的落实没有完全到位。\n  三、改进建议：1.礼敬传统，保留非遗完整结构与秩序，重视非遗生存环境的整体性保护，确保原真性。2.社会\n各界给予更多关注，在资金场地上进一步提供保障。3.对传承人进行严格考核，保证带徒授艺规范有序。4.进行符合\n文化演化规律的延展，深入了解后选择更有利的保护、传承和活化方式。\n  参考答案说明：（1）格式方面，本参考答案写到了“标题”“正文”两个部分。（2）正文部分，一方面从内容上来\n看，本参考答案的开头先介绍了本次座谈会的背景信息。其次，主体部分具体介绍了非遗法实施所取得的成效、存\n在的不足和改进建议。另一方面，形式上，本参考答案做到了分段、分条撰写，整体上条理较为清晰。","figs":[],"state":"已标记","notes":[],"domains":["文化","法律","公共管理"],"nature":"综合题","current":false}},"materialFiles":{"e98d4ffa1f6cfa25":"eea18bc9e38f223c10741fac","6644520b217e1626":"48526faa975a5120c75076ed","79740cef9272f9f5":"33e0402491158a6605757260"},"terms":{"k-713e68763e49192b":{"id":"k-713e68763e49192b","mode":"k","type":"观点与论证","title":"凤凰河生态复苏与文化传承","qs":[],"count":1},"k-c7fdb9fb3d9a8a38":{"id":"k-c7fdb9fb3d9a8a38","mode":"k","type":"观点与论证","title":"流域文化遗产保护的全流域协调","qs":[],"count":1},"k-6c17be7420f2871c":{"id":"k-6c17be7420f2871c","mode":"k","type":"方法与技能","title":"流域文化核心内容提炼","qs":[],"count":1},"k-5f0693bbb316def1":{"id":"k-5f0693bbb316def1","mode":"k","type":"观点与论证","title":"生态旅游与文化旅游融合","qs":[],"count":1},"k-77b440d77f8e1fc4":{"id":"k-77b440d77f8e1fc4","mode":"k","type":"观点与论证","title":"文化资源活化利用","qs":[],"count":1},"s-171ebed39b4fe1cf":{"id":"s-171ebed39b4fe1cf","mode":"s","type":"应用文写作","title":"汇报与交流发言","qs":[],"count":5},"s-ecba3f8c2c1d3b9b":{"id":"s-ecba3f8c2c1d3b9b","mode":"s","type":"提出对策","title":"将外地经验转化为本地措施","qs":[],"count":6},"k-3e95b77eeabd0099":{"id":"k-3e95b77eeabd0099","mode":"k","type":"概念与词义","title":"高标准农田","qs":[],"count":4},"k-7abd42f3d3e3ebc0":{"id":"k-7abd42f3d3e3ebc0","mode":"k","type":"原理与机制","title":"农田连片整合与土地流转","qs":[],"count":1},"k-be0407994ebcc946":{"id":"k-be0407994ebcc946","mode":"k","type":"原理与机制","title":"农田基础设施改善与特色农业发展","qs":[],"count":1},"k-e6fbd439ca279965":{"id":"k-e6fbd439ca279965","mode":"k","type":"制度与规则","title":"高标准农田的粮食生产用途要求","qs":[],"count":1},"k-fbe56f334fecd67b":{"id":"k-fbe56f334fecd67b","mode":"k","type":"制度与规则","title":"高标准农田项目设计变更与验收","qs":[],"count":1},"k-abf275cf7d287f0a":{"id":"k-abf275cf7d287f0a","mode":"k","type":"概念与词义","title":"田间道","qs":[],"count":1},"k-1d9d287163ec3883":{"id":"k-1d9d287163ec3883","mode":"k","type":"制度与规则","title":"C市高标准农田有机肥施用要求","qs":[],"count":1},"s-c6bd983baf5dd3ae":{"id":"s-c6bd983baf5dd3ae","mode":"s","type":"提出对策","title":"根据问题成因逐项提出措施","qs":[],"count":8},"k-617bc5b51533628c":{"id":"k-617bc5b51533628c","mode":"k","type":"事实与事件","title":"非遗法实施对企业的作用","qs":[],"count":1},"k-663932a5e61c3ed9":{"id":"k-663932a5e61c3ed9","mode":"k","type":"事实与事件","title":"非遗法实施与民间文化价值认知","qs":[],"count":1},"k-ccaa22104463ae9e":{"id":"k-ccaa22104463ae9e","mode":"k","type":"观点与论证","title":"非遗传承的资金与场地保障","qs":[],"count":1},"k-b7e2ea515f503791":{"id":"k-b7e2ea515f503791","mode":"k","type":"概念与词义","title":"非物质文化遗产","qs":[],"count":1},"k-e6158c82c8dad87b":{"id":"k-e6158c82c8dad87b","mode":"k","type":"事实与事件","title":"非遗保护人才队伍的能力差距","qs":[],"count":1},"k-46193cdb17edb9e5":{"id":"k-46193cdb17edb9e5","mode":"k","type":"观点与论证","title":"非遗传承中的知识产权认定","qs":[],"count":1},"k-c2744839d74471e4":{"id":"k-c2744839d74471e4","mode":"k","type":"事实与事件","title":"非遗法在部分地方落实不到位","qs":[],"count":1},"k-7aba68b5e065012d":{"id":"k-7aba68b5e065012d","mode":"k","type":"观点与论证","title":"非遗原真性与整体性保护","qs":[],"count":1},"k-8b0c3c8f8ca79697":{"id":"k-8b0c3c8f8ca79697","mode":"k","type":"观点与论证","title":"非遗代表性传承人的带徒授艺考核","qs":[],"count":1},"k-386ce3913640401f":{"id":"k-386ce3913640401f","mode":"k","type":"观点与论证","title":"非遗活化与文化演化规律","qs":[],"count":1}},"questions":{}},"firstMaterials":[{"key":"e98d4ffa1f6cfa25","value":["材料3","材料3\n  大自然孕育河流，河流哺育城市。自古以来，城市的兴起与繁华和河流有着鱼水相依的密切联系。对于J市来\n说，拥有一条穿城而过的凤凰河，实属它的幸运。一脉清流，自雷山南麓而出，在J市北部与梨河交汇后，滔滔河水\n夹带着巨量泥沙，沿着大峡谷奔流而下，离开山口后水势变缓，泥沙就沉积在了今天J市所在地，逐渐形成适合居住\n的平原。凤凰河还带来大量的淡水资源，为人们提供了可生息繁衍的得天独厚的自然条件。于是，这里从最初的简\n单村落逐步发展成了人口密集的城市。\n  在漕运发达的年代，凤凰河南北客商云集，行旅往来不绝。凤凰河哺育了两岸百姓，带来了数百年的繁华，也\n留下了宝贵的文化遗产。凤凰河流域涵盖了旧石器时代遗址、新石器时代遗址以及红色文化纪念地、现代工业遗址\n等各类物质和非物质文化遗产。可以说，凤凰河不仅是一条养育城市和居民的水脉，更是一条承载文化交流、传播\n文明成果的文脉。\n  J市文史专家叶教授这些年一直在对凤凰河流域文化进行考察调研，他说：“凤凰河流域文化曾经是灿烂辉煌的，\n但有一段时期河中都没有水，没有水，还能称为河吗？”上世纪70年代后期以来，由于人们对山上林木的砍伐，凤凰\n河上游水土大量流失，加之降水量减少了十分之一左右，以及逐层筑坝拦截用水等诸多原因，凤凰河多处河段干\n涸、生态系统严重退化，资源性缺水成了凤凰河的软肋。没有了水，凤凰河流动的“血脉”不再畅通，曾经雄伟的高楼\n宝塔犹如聚沙而起，那些河边的饮食起居变得黯淡无光，那些鲜活的戏曲说唱逐渐销声匿迹，那些依河而兴的市镇\n村庄失去了往日的生机。\n\n  令人欣慰的是，近几年来，在全国生态环境治理的大背景下，凤凰河流域的各级政府也下大力气治理河流，清\n淤疏浚河道，垒坝稳固河槽，关停污染企业，绿化河岸环境。但沿线各城市经济发展水平不同，利益诉求也不尽相\n同，难免出现矛盾冲突。如何破局，关键在于树立全流域“一盘棋”意识。2018年5月，凤凰河综合治理与生态修复协\n调领导小组正式成立，领导小组的使命很明确：通过制定年度工作要点、加强沟通协调、严格监督检查，破解跨省\n城、协调难等治理难题。同时，《凤凰河流域水资源保护规划》《凤凰河流域水资源综合规划》等专业规划陆续出\n台。经过3年努力，2021年，凤凰河终于实现25年来的首次全线通水。“水运连着城运，更连着千家万户。水资源格\n局决定和影响城市发展格局。凤凰河‘复活’后，将极大促进沿岸经济文化的发展。”叶教授说。\n  恢复凤凰河流域生态系统是一项长期工程，全线通水不再断流，是推进凤凰河流域生态环境复苏的第一步。流\n动的河能激活文化之河，文化之河也能反哺流动的河，现在宣传和弘扬凤凰河流域文化恰逢其时。叶教授曾经问过\n凤凰河附近的居民，什么是凤凰河流域文化。“有说文明起源的，有说民族融合的，有说拼搏奋斗精神的，总之是太\n杂了。凤凰河流域文化确实多姿多彩，但我们要从中提炼出最精彩、最个性、最具张力的核心内容。”叶教授说。数\n年前，J市文化部门曾联合研究机构开展过一次凤凰河流域考古调查，但流域的文化遗产分布涉及沿岸五省多个县\n市，保护和开发情况各有不同，调查无法整体推进。“如果我们都没有对凤凰河流域文化内涵进行深入挖掘，又怎么\n能要求群众了解？”此外，还有一点令叶教授觉得遗憾，就是之前凤凰河流域文化保护传承多是在文化部门制定的政\n策框架下进行，无法统筹流域内相关部门形成保护合力，流域文化遗产系统性保护传承战略规划、体制机制的问题\n都没有根本解决。经过多年调研，凤凰河生态治理的模式给了叶教授新的启发。\n  “文化的生命在于‘用’，在于融入群众生活。如何用？凤凰河沿岸历史遗迹、红色文化等资源这么丰富，正适合发\n展文化旅游。而生态环境是文化旅游的稀缺资源和宝贵财富，如果能真正恢复凤凰河以前的自然风光和生态环境，\n就可以推动生态旅游和文化旅游融合发展，让大众在‘用’中接触到‘活’的凤凰河流域文化。”叶教授说，“沿河也可以修\n建更多现代化的文化景观，在古今辉映中汇聚凤凰河文化的人气。像之前有人提议筹建凤凰河博物馆，就是很好的\n思路。随着数字化时代的来临，我们还可以开发‘凤河游’App，让游客沉浸式体验虚拟和现实结合的数字凤凰河新景\n观，感受‘活’起来的凤凰河流域文化。”",["1b62f4f7aa551cdd783e.pdf",2]],"label":"国考 2023 副省级 申论|材料3"}],"node":{"id":"s-171ebed39b4fe1cf","mode":"s","title":"汇报与交流发言","type":"应用文写作","domain":"文化","reading":"","intro":"","priority":100,"aliases":["按意义、问题和对策归纳材料并组织正文","从调研材料中归纳建设成效与实施问题","按成效、不足和改进建议归并多方座谈发言","从现场检查材料归并工作成效与执行问题","从培训见闻中提炼共同主题并按工作维度归纳心得","撰写情况汇报与发言提纲","撰写学习交流发言稿"],"qs":["国考 2023 副省级 申论#3","国考 2024 副省级 申论#4","国考 2024 行政执法 申论#3","国考 2025 行政执法 申论#4","江苏 2024 C类 申论#4"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"method":"根据听众和发言目的，提取需要汇报的事实、做法与体会，按议题安排先后。","subject":"申论","publishedSets":[{"name":"汇报与交流发言","ids":["国考 2023 副省级 申论#3","国考 2024 副省级 申论#4","国考 2024 行政执法 申论#3","国考 2025 行政执法 申论#4","江苏 2024 C类 申论#4"],"units":[["国考 2023 副省级 申论#3"],["国考 2024 副省级 申论#4"],["国考 2024 行政执法 申论#3"],["国考 2025 行政执法 申论#4"],["江苏 2024 C类 申论#4"]]}]}};
